import type { AuthUser } from '../auth/interfaces/auth-user.interface';
import {
  Controller,
  Get,
  Param,
  Query,
  UseGuards,
  Req,
  Res,
  NotFoundException,
} from '@nestjs/common';
import type { Request, Response } from 'express';
import { AuditService } from './audit.service';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { PermissionsGuard } from '../auth/guards/permissions.guard';
import { RequirePermissions } from '../auth/decorators/permissions.decorator';
import { QueryAuditLogsDto } from './dto/query-audit-logs.dto';

@Controller('audit-logs')
@UseGuards(JwtAuthGuard, PermissionsGuard)
export class AuditController {
  constructor(private readonly auditService: AuditService) {}

  @Get()
  @RequirePermissions({ action: 'read', subject: 'AuditLog' })
  async findAll(@Query() query: QueryAuditLogsDto, @Req() req: Request) {
    return this.auditService.findAll(
      {
        action: query.action,
        userId: query.userId,
        subjectId: query.subjectId,
        subject: query.subject,
        search: query.search,
        tk: query.tk,
        // v0.29 fix: normalize date-only input để dateTo `2026-05-20` cover hết ngày.
        dateFrom: query.dateFrom
          ? normalizeStartOfDay(query.dateFrom)
          : undefined,
        dateTo: query.dateTo ? normalizeEndOfDay(query.dateTo) : undefined,
        limit: query.limit,
        offset: query.offset,
      },
      (req.user as AuthUser)?.id,
    );
  }

  // v0.29: detail endpoint — returns raw sanitized metadata for modal view.
  @Get('actions')
  @RequirePermissions({ action: 'read', subject: 'AuditLog' })
  async actions(@Req() req: Request): Promise<string[]> {
    return this.auditService.distinctActions((req.user as AuthUser)?.id);
  }

  @Get('subjects')
  @RequirePermissions({ action: 'read', subject: 'AuditLog' })
  async subjects(@Req() req: Request): Promise<string[]> {
    return this.auditService.distinctSubjects((req.user as AuthUser)?.id);
  }

  // v0.29: streaming CSV export with formula sanitization + 10k cap.
  @Get('export.csv')
  @RequirePermissions({ action: 'read', subject: 'AuditLog' })
  async exportCsv(
    @Query() query: QueryAuditLogsDto,
    @Req() req: Request,
    @Res() res: Response,
  ): Promise<void> {
    const userId = (req.user as AuthUser)?.id;
    const ipAddress = req.ip;
    const userAgent = req.headers['user-agent'];

    const { data } = await this.auditService.findAll(
      {
        action: query.action,
        userId: query.userId,
        subjectId: query.subjectId,
        subject: query.subject,
        search: query.search,
        // Xuất CSV áp CÙNG thẻ như danh sách — bỏ thẻ là tệp chứa bản ghi màn không hiện.
        tk: query.tk,
        dateFrom: query.dateFrom
          ? normalizeStartOfDay(query.dateFrom)
          : undefined,
        dateTo: query.dateTo ? normalizeEndOfDay(query.dateTo) : undefined,
        limit: 10000,
        offset: 0,
        forExport: true,
      },
      (req.user as AuthUser)?.id,
    );

    // Audit-of-export: log this export action itself.
    await this.auditService.log({
      userId,
      action: 'AUDIT_LOG_EXPORTED',
      subject: 'AuditLog',
      metadata: { rowCount: data.length, filters: query as any },
      ipAddress,
      userAgent,
    });

    const filename = `audit-logs-${new Date().toISOString().split('T')[0]}.csv`;
    res.setHeader('Content-Type', 'text/csv; charset=utf-8');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);

    // Stream header + rows.
    res.write('﻿'); // BOM for Excel UTF-8
    res.write(
      'Thời gian,Người dùng,Action,Subject,SubjectID,Số trường thay đổi,IP\n',
    );
    for (const row of data) {
      const user = (row as any).user;
      const userName = user
        ? `${user.firstName ?? ''} ${user.lastName ?? ''}`.trim() ||
          user.username ||
          ''
        : '';
      const changedCount = (row as any).changedFields?.length ?? 0;
      const cols = [
        new Date(row.createdAt).toISOString(),
        userName,
        row.action,
        row.subject ?? '',
        row.subjectId ?? '',
        String(changedCount),
        row.ipAddress ?? '',
      ].map(sanitizeCsvCell);
      res.write(cols.join(',') + '\n');
    }
    res.end();
  }

  @Get(':id')
  @RequirePermissions({ action: 'read', subject: 'AuditLog' })
  async findById(@Param('id') id: string, @Req() req: Request) {
    const row = await this.auditService.findById(
      id,
      (req.user as AuthUser)?.id,
    );
    if (!row) throw new NotFoundException('Audit log not found');
    return row;
  }
}

/**
 * v0.29 fix: date-only input → ISO timestamp start-of-day (UTC).
 * Ex: "2026-05-20" → "2026-05-20T00:00:00.000Z"
 */
function normalizeStartOfDay(input: string): Date {
  const d = new Date(input);
  // Nếu input đã có timezone/time → giữ nguyên. Date-only → set start of day.
  if (input.length <= 10) {
    return new Date(input + 'T00:00:00.000Z');
  }
  return d;
}

/**
 * v0.29 fix: date-only input → end-of-day (UTC). Khắc phục bug dateTo bỏ sót logs.
 */
function normalizeEndOfDay(input: string): Date {
  if (input.length <= 10) {
    return new Date(input + 'T23:59:59.999Z');
  }
  return new Date(input);
}

/**
 * v0.29: Sanitize CSV cell to prevent Excel formula injection.
 * OWASP: cells starting with =/+/-/@/tab/CR/LF can execute formulas in Excel/Sheets.
 * Strategy: prefix with single quote `'` + quote-escape.
 */
function sanitizeCsvCell(value: string): string {
  if (value == null) return '';
  const str = String(value);
  // Formula injection prefix sanitization
  const safe = /^[=+\-@\t\r]/.test(str) ? "'" + str : str;
  // CSV escape: quote field if contains comma, quote, or newline
  if (/[",\n\r]/.test(safe)) {
    return '"' + safe.replace(/"/g, '""') + '"';
  }
  return safe;
}

import { CaseAuditPolicyService } from './case-audit-policy.service';
import { CaseGovernanceService } from '../cases/governance/case-governance.service';
import { CaseFieldSchemaService } from '../cases/governance/case-field-schema.service';
import { Injectable, Optional } from '@nestjs/common';
import { randomUUID } from 'node:crypto';
import { Prisma } from '@prisma/client';
import { PrismaService } from '../prisma/prisma.service';
import {
  sanitizePII,
  computeFieldDiff,
  ChangedField,
  sanitizeMetadataRecursive,
} from './audit.utils';
import { BoTimKiem } from '../common/tim-kiem/bo-tim-kiem';
import { KHOA_TAT_CA, noiVaoWhere } from '../common/tim-kiem/dieu-kien';
import { KHAI_TIM_KIEM_NHAT_KY } from '../common/tim-kiem/khai/nhat-ky.khai';

export interface AuditLogCreateInput {
  userId?: string;
  action: string;
  subject?: string;
  subjectId?: string;
  metadata?: Record<string, unknown>;
  ipAddress?: string;
  userAgent?: string;
}

export interface FindAllParams {
  action?: string;
  userId?: string;
  subjectId?: string;
  subject?: string;
  /** Ô tìm cũ — quy về thẻ "tất cả các cột" (gồm tên người thực hiện). */
  search?: string;
  /** Thẻ tìm kiếm `khoá~giá trị` (khai nhat-ky); khoá lạ → 400. */
  tk?: string[];
  dateFrom?: Date;
  dateTo?: Date;
  limit?: number;
  offset?: number;
  /** v0.29 fix: internal-only flag để bypass LIMIT_MAX clamp cho export endpoint. */
  forExport?: boolean;
}

// v0.29 bounds — defense in depth. Controller DTO cũng validate, đây là safety net.
const LIMIT_MIN = 1;
const LIMIT_MAX = 100;
const LIMIT_EXPORT_MAX = 10000;
const LIMIT_DEFAULT = 20;

/** `search` cũ → thẻ "tất cả các cột". */
const THAM_SO_CU_NHAT_KY = { search: KHOA_TAT_CA } as const;

@Injectable()
export class AuditService {
  private boTimKiem?: BoTimKiem;

  private get timKiem(): BoTimKiem {
    return (this.boTimKiem ??= new BoTimKiem(
      this.prisma,
      KHAI_TIM_KIEM_NHAT_KY,
      THAM_SO_CU_NHAT_KY,
    ));
  }

  constructor(
    private readonly prisma: PrismaService,
    @Optional() private readonly injectedCasePolicy?: CaseAuditPolicyService,
  ) {}
  private get casePolicy(): CaseAuditPolicyService {
    if (this.injectedCasePolicy) return this.injectedCasePolicy;
    const core = new CaseGovernanceService(this.prisma);
    return new CaseAuditPolicyService(
      this.prisma,
      core,
      new CaseFieldSchemaService(this.prisma, core),
    );
  }

  async log(
    input: AuditLogCreateInput,
    tx?: Prisma.TransactionClient,
  ): Promise<void> {
    const client = tx ?? this.prisma;
    // v0.29: sanitize metadata ở log() để mọi caller (kể cả audit.log direct, không
    // qua wrapUpdate) đều được protect. Recursive cho before/after nested objects.
    const safeMetadata = input.metadata
      ? sanitizeMetadataRecursive(input.metadata)
      : null;
    // Use $executeRaw to bypass Prisma's strict relation typing for userId
    await client.$executeRaw`
      INSERT INTO "audit_logs" (id, "userId", action, subject, "subjectId", metadata, "ipAddress", "userAgent", "createdAt")
      VALUES (
        gen_random_uuid()::text,
        ${input.userId ?? null},
        ${input.action},
        ${input.subject ?? null},
        ${input.subjectId ?? null},
        ${safeMetadata ? JSON.stringify(safeMetadata) : null}::jsonb,
        ${input.ipAddress ?? null},
        ${input.userAgent ?? null},
        NOW()
      )
    `;
  }

  /**
   * v0.29: wrap an update flow — fetch before-snapshot, run update, audit with sanitized before/after.
   *
   * Critical PII fix: applies `sanitizePII` to `before` and `after` BEFORE persisting metadata.
   * passwordHash, refreshTokenHash, totpSecret, backupCodes, etc. never land in audit_logs.
   *
   * Optional `tx` parameter — caller can wrap whole flow in 1 transaction (fetch + update + log atomic).
   */
  async wrapUpdate<T>(opts: {
    fetchFn: () => Promise<T>;
    updateFn: () => Promise<T>;
    action: string;
    subject: string;
    subjectId: string;
    userId: string;
    meta?: { ipAddress?: string; userAgent?: string };
    tx?: Prisma.TransactionClient;
  }): Promise<T> {
    const before = await opts.fetchFn();
    const after = await opts.updateFn();
    // v0.29: sanitize PII before storing
    const sanitizedBefore = sanitizePII(before as Record<string, unknown>);
    const sanitizedAfter = sanitizePII(after as Record<string, unknown>);
    await this.log(
      {
        userId: opts.userId,
        action: opts.action,
        subject: opts.subject,
        subjectId: opts.subjectId,
        metadata: { before: sanitizedBefore, after: sanitizedAfter },
        ipAddress: opts.meta?.ipAddress,
        userAgent: opts.meta?.userAgent,
      },
      opts.tx,
    );
    return after;
  }

  // ───────────────────────────────────────────────
  // v0.48 PR1 B2 — Bulk operations audit
  // logBulkHeader (outside tx, status STARTED) → loop runBulk per item
  //   calling logBulkItem (inside tx, atomic với data write) → completeBulk
  //   (outside tx, status COMPLETED + counts). Plan eng E-H3 atomicity model.
  // ───────────────────────────────────────────────

  /**
   * Tạo 1 header row trong `bulk_operations` với status STARTED.
   * Caller giữ `bulkOperationId` trả về để: (1) pass cho `logBulkItem` mỗi item,
   * (2) gọi `completeBulk` cuối loop. Idempotency key optional cho retry-safe
   * (plan eng E-H10) — combo `(actorId, idempotencyKey)` UNIQUE ở DB layer.
   */
  async logBulkHeader(input: {
    actorId: string;
    resource: string;
    action: string;
    idempotencyKey?: string;
  }): Promise<{ bulkOperationId: string }> {
    const id = randomUUID();
    try {
      await this.prisma.$executeRaw`
        INSERT INTO "bulk_operations" (
          id, "actorId", resource, action, status, "idempotencyKey", "startedAt"
        ) VALUES (
          ${id},
          ${input.actorId},
          ${input.resource},
          ${input.action},
          'STARTED'::"BulkOperationStatus",
          ${input.idempotencyKey ?? null},
          NOW()
        )
      `;
      return { bulkOperationId: id };
    } catch (e) {
      // Codex post-deploy P2 fix: retry với same idempotencyKey không nên crash.
      // P2002 = Prisma unique constraint violation. UNIQUE (actorId, idempotencyKey)
      // → caller retry trên cùng request → trả lại bulkOperationId hiện có.
      // KHÔNG có idempotencyKey → bug thực sự, rethrow.
      if (input.idempotencyKey && (e as { code?: string })?.code === 'P2002') {
        const existing = await this.prisma.$queryRaw<{ id: string }[]>`
          SELECT id FROM "bulk_operations"
          WHERE "actorId" = ${input.actorId}
            AND "idempotencyKey" = ${input.idempotencyKey}
          LIMIT 1
        `;
        if (existing.length > 0) {
          return { bulkOperationId: existing[0].id };
        }
      }
      throw e;
    }
  }

  /**
   * Ghi 1 item row vào audit_logs với `bulkOperationId` set. PHẢI gọi inside tx
   * của data write (plan eng E-H3): rollback đồng bộ nếu Case update fail thì
   * audit row cũng rollback. Caller truyền `tx` từ `prisma.$transaction(...)`.
   * Bỏ tx → fallback ghi qua prisma chính (chỉ cho test/internal use).
   */
  async logBulkItem(
    input: {
      bulkOperationId: string;
      userId: string;
      action: string;
      subject: string;
      subjectId: string;
      metadata?: Record<string, unknown>;
      ipAddress?: string;
      userAgent?: string;
    },
    tx?: Prisma.TransactionClient,
  ): Promise<void> {
    const client = tx ?? this.prisma;
    const safeMetadata = input.metadata
      ? sanitizeMetadataRecursive(input.metadata)
      : null;
    await client.$executeRaw`
      INSERT INTO "audit_logs" (
        id, "userId", action, subject, "subjectId", metadata,
        "ipAddress", "userAgent", "bulkOperationId", "createdAt"
      ) VALUES (
        gen_random_uuid()::text,
        ${input.userId},
        ${input.action},
        ${input.subject},
        ${input.subjectId},
        ${safeMetadata ? JSON.stringify(safeMetadata) : null}::jsonb,
        ${input.ipAddress ?? null},
        ${input.userAgent ?? null},
        ${input.bulkOperationId},
        NOW()
      )
    `;
  }

  /**
   * Cập nhật header row sau khi loop xong: status COMPLETED|FAILED, counts,
   * completedAt. Gọi OUTSIDE per-item tx (sau khi runBulk return).
   * `status` mặc định 'COMPLETED'; gọi với 'FAILED' khi toàn bộ batch fail
   * (vd preflight throw).
   */
  async completeBulk(
    bulkOperationId: string,
    counts: {
      succeeded: number;
      skipped: number;
      failed: number;
      status?: 'COMPLETED' | 'FAILED';
    },
  ): Promise<void> {
    const status = counts.status ?? 'COMPLETED';
    await this.prisma.$executeRaw`
      UPDATE "bulk_operations"
      SET status = ${status}::"BulkOperationStatus",
          "succeededCount" = ${counts.succeeded},
          "skippedCount" = ${counts.skipped},
          "failedCount" = ${counts.failed},
          "completedAt" = NOW()
      WHERE id = ${bulkOperationId}
    `;
  }

  async findAll(params: FindAllParams, actorId?: string) {
    const { action, userId, subjectId, subject, dateFrom, dateTo } = params;

    // v0.29: clamp limit. Public list path: [LIMIT_MIN, LIMIT_MAX=100].
    // Export path (forExport=true): up to LIMIT_EXPORT_MAX=10k for CSV bulk download.
    const maxLimit = params.forExport ? LIMIT_EXPORT_MAX : LIMIT_MAX;
    let limit = params.limit ?? LIMIT_DEFAULT;
    if (!Number.isFinite(limit)) limit = LIMIT_DEFAULT;
    limit = Math.max(LIMIT_MIN, Math.min(maxLimit, Math.floor(limit)));
    let offset = params.offset ?? 0;
    if (!Number.isFinite(offset)) offset = 0;
    offset = Math.max(0, Math.floor(offset));

    const where: Prisma.AuditLogWhereInput = {
      ...(action && { action }),
      ...(userId && { userId }),
      ...(subjectId && { subjectId }),
      ...(subject && { subject }),
      ...((dateFrom || dateTo) && {
        createdAt: {
          ...(dateFrom && { gte: dateFrom }),
          ...(dateTo && { lte: dateTo }),
        },
      }),
    };
    // Thẻ tìm kiếm (`tk` + `search` cũ) — bỏ dấu, chọn cột, khoá lạ → 400; "*" gồm tên người thực hiện.
    // Thoát `%`/`_` và cắt độ dài nằm trong common/tim-kiem. Trước đây OR `contains` thường trên
    // action/subject/subjectId, còn tên người thì màn lọc lại trên trang đã tải — không bao giờ ra.
    noiVaoWhere(
      where as Record<string, unknown>,
      await this.timKiem.dieuKien(params),
    );

    noiVaoWhere(where as Record<string, unknown>, [
      await this.casePolicy.predicate(actorId),
    ]);
    const [rawData, total] = await Promise.all([
      this.prisma.auditLog.findMany({
        where,
        include: {
          user: {
            select: {
              id: true,
              firstName: true,
              lastName: true,
              username: true,
            },
          },
        },
        // v0.29: bug fix — DESC để newest first (audit log convention)
        orderBy: { createdAt: 'desc' },
        take: limit,
        skip: offset,
      }),
      this.prisma.auditLog.count({ where }),
    ]);

    for (let index = 0; index < rawData.length; index++)
      rawData[index] = await this.casePolicy.sanitize(
        rawData[index],
        actorId,
        params.forExport ? 'export' : 'read',
      );
    // v0.29: compute changedFields per row from metadata.before/after.
    // Strip raw before/after from list response to reduce payload (detail endpoint returns raw).
    const data = rawData.map((row) => {
      const meta = (row.metadata ?? null) as Record<string, unknown> | null;
      let changedFields: ChangedField[] = [];
      if (meta && (meta.before || meta.after)) {
        changedFields = computeFieldDiff(
          (meta.before as Record<string, unknown>) ?? null,
          (meta.after as Record<string, unknown>) ?? null,
        );
      }
      // Strip before/after, keep other metadata keys.
      const { before: _b, after: _a, ...restMeta } = meta ?? {};
      return {
        ...row,
        metadata: Object.keys(restMeta).length > 0 ? restMeta : null,
        changedFields,
      };
    });

    return { data, total, limit, offset };
  }

  /**
   * v0.29: detail endpoint — returns raw sanitized metadata (full before/after).
   */
  async findById(id: string, actorId?: string) {
    let row = await this.prisma.auditLog.findUnique({
      where: { id, AND: [await this.casePolicy.predicate(actorId)] },
      include: {
        user: {
          select: { id: true, firstName: true, lastName: true, username: true },
        },
      },
    });
    if (!row) return null;
    row = await this.casePolicy.sanitize(row, actorId);
    const meta = (row.metadata ?? null) as Record<string, unknown> | null;
    let changedFields: ChangedField[] = [];
    if (meta && (meta.before || meta.after)) {
      changedFields = computeFieldDiff(
        (meta.before as Record<string, unknown>) ?? null,
        (meta.after as Record<string, unknown>) ?? null,
      );
    }
    return { ...row, changedFields };
  }

  /**
   * v0.29: distinct action names for filter dropdown.
   */
  async distinctActions(actorId?: string): Promise<string[]> {
    const rows = await this.prisma.auditLog.findMany({
      where: { AND: [await this.casePolicy.predicate(actorId)] },
      select: { action: true },
      distinct: ['action'],
      orderBy: { action: 'asc' },
    });
    return rows.map((r) => r.action);
  }

  /**
   * v0.29: distinct subject types for filter dropdown.
   */
  async distinctSubjects(actorId?: string): Promise<string[]> {
    const rows = await this.prisma.auditLog.findMany({
      select: { subject: true },
      distinct: ['subject'],
      where: {
        subject: { not: null },
        AND: [await this.casePolicy.predicate(actorId)],
      },
      orderBy: { subject: 'asc' },
    });
    return rows.map((r) => r.subject!).filter(Boolean);
  }
}
